sap.ui.define([                                                                                                                                                                                                                                                
  "sap/ui/core/mvc/Controller", "sap/m/MessageBox", "sap/ui/model/Sorter", "jquery.sap.global", "chorus/bpc/objects/model/Archive"                                                                                                                             
], function (Controller, MessageBox, Sorter, jQuery, Archive) {                                                                                                                                                                                                
  "use strict";                                                                                                                                                                                                                                                
  return Controller.extend("chorus.bpc.objects.controller.App", {                                                                                                                                                                                              
    onInit: function () {                                                                                                                                                                                                                                      
      this._generation = 0;                                                                                                                                                                                                                                    
      this._compareSequence = 0;                                                                                                                                                                                                                               
      this._requests = [];                                                                                                                                                                                                                                     
      this._scripts = [];                                                                                                                                                                                                                                      
      this._packages = [];                                                                                                                                                                                                                                     
      this._sorter = new Sorter("category", false, function (oContext) {                                                                                                                                                                                       
        var sCategory = oContext.getProperty("category");                                                                                                                                                                                                      
        return { key: sCategory, text: sCategory };                                                                                                                                                                                                            
      });                                                                                                                                                                                                                                                      
      Promise.resolve().then(function () {                                                                                                                                                                                                                     
        if (this._destroyed) { return; }                                                                                                                                                                                                                       
        this._data = this.getOwnerComponent().getModel("bpc");                                                                                                                                                                                                 
        this._set("busy", true);                                                                                                                                                                                                                               
        this._request("environments", {}).then(function (oData) {                                                                                                                                                                                              
          if (this._destroyed) { return; }                                                                                                                                                                                                                     
          if (!Array.isArray(oData.environments)) { throw new Error("Invalid environment response."); }                                                                                                                                                        
          this._set("environments", oData.environments);                                                                                                                                                                                                       
          this._set("status", oData.environments.length ? "Select an environment and model." : "No environments available.");                                                                                                                                  
          this._set("busy", false);                                                                                                                                                                                                                            
        }.bind(this)).catch(this._error.bind(this));                                                                                                                                                                                                           
      }.bind(this));                                                                                                                                                                                                                                           
    },                                                                                                                                                                                                                                                         
    _set: function (sPath, vValue) { this._data.setProperty("/" + sPath, vValue); },                                                                                                                                                                           
    _get: function (sPath) { return this._data.getProperty("/" + sPath); },                                                                                                                                                                                    
    _request: function (sResource, mParams, sMethod) {                                                                                                                                                                                                         
      var sClient = jQuery.sap.getUriParameters().get("sap-client");                                                                                                                                                                                           
      if (sClient) { mParams["sap-client"] = sClient; }                                                                                                                                                                                                        
      return new Promise(function (resolve, reject) {                                                                                                                                                                                                          
        var oXHR = jQuery.ajax({ url: "/sap/bc/zbpc_io/" + sResource, type: sMethod || "GET", dataType: "json", data: mParams,                                                                                                                                 
          timeout: 60000,                                                                                                                                                                                                                                      
          success: resolve,                                                                                                                                                                                                                                    
          error: function (oResponse, sStatus) {                                                                                                                                                                                                               
            var oError = new Error(oResponse.responseJSON && oResponse.responseJSON.error ?                                                                                                                                                                    
              oResponse.responseJSON.error.message : "Cannot load " + sResource + ". Check your SAP session and access.");                                                                                                                                     
            oError.status = oResponse.status;                                                                                                                                                                                                                  
            oError.aborted = sStatus === "abort";                                                                                                                                                                                                              
            reject(oError);                                                                                                                                                                                                                                    
          },                                                                                                                                                                                                                                                   
          complete: function () { this._requests = this._requests.filter(function (oItem) { return oItem !== oXHR; }); }.bind(this)                                                                                                                            
        });                                                                                                                                                                                                                                                    
        this._requests.push(oXHR);                                                                                                                                                                                                                             
      }.bind(this));                                                                                                                                                                                                                                           
    },                                                                                                                                                                                                                                                         
    _error: function (oError) {                                                                                                                                                                                                                                
      if (this._destroyed || oError.aborted) { return; }                                                                                                                                                                                                       
      this._set("busy", false);                                                                                                                                                                                                                                
      this._set("importBusy", false);                                                                                                                                                                                                                          
      this._set("status", oError.message);                                                                                                                                                                                                                     
      MessageBox.error(oError.message);                                                                                                                                                                                                                        
    },                                                                                                                                                                                                                                                         
    _resetObjects: function () {                                                                                                                                                                                                                               
      this._generation++;                                                                                                                                                                                                                                      
      this._compareSequence++;                                                                                                                                                                                                                                 
      this._scripts = [];                                                                                                                                                                                                                                      
      this._packages = [];                                                                                                                                                                                                                                     
      this._set("objects", []);                                                                                                                                                                                                                                
      this._set("uploaded", []);                                                                                                                                                                                                                               
      this._set("archivePackages", []);                                                                                                                                                                                                                        
      this._set("selectedCount", 0);                                                                                                                                                                                                                           
      this._set("objectsLoaded", false);                                                                                                                                                                                                                       
      this._set("importResults", []);                                                                                                                                                                                                                          
      this._set("importSummary", "");                                                                                                                                                                                                                          
      this._set("packageImportSummary", "");                                                                                                                                                                                                                   
      var oList = this.byId("objects");                                                                                                                                                                                                                        
      if (oList) { oList.removeSelections(true); }                                                                                                                                                                                                             
      return this._generation;                                                                                                                                                                                                                                 
    },                                                                                                                                                                                                                                                         
    onEnvironmentChange: function () {                                                                                                                                                                                                                         
      var iGeneration = this._resetObjects();                                                                                                                                                                                                                  
      this._set("models", []);                                                                                                                                                                                                                                 
      this._set("model", "");                                                                                                                                                                                                                                  
      var sEnvironment = this._get("environment");                                                                                                                                                                                                             
      if (!sEnvironment) { return; }                                                                                                                                                                                                                           
      this._set("busy", true);                                                                                                                                                                                                                                 
      this._set("status", "Loading models...");                                                                                                                                                                                                                
      this._request("models", { environment: sEnvironment }).then(function (oData) {                                                                                                                                                                           
        if (this._destroyed || iGeneration !== this._generation) { return; }                                                                                                                                                                                   
        if (!Array.isArray(oData.models)) { throw new Error("Invalid model response."); }                                                                                                                                                                      
        this._set("models", oData.models);                                                                                                                                                                                                                     
        this._set("busy", false);                                                                                                                                                                                                                              
        this._set("status", oData.models.length ? "Select a model to browse its objects." : "No models available.");                                                                                                                                           
      }.bind(this)).catch(function (e) { if (iGeneration === this._generation) { this._error(e); } }.bind(this));                                                                                                                                              
    },                                                                                                                                                                                                                                                         
    onModelChange: function (oEvent) {                                                                                                                                                                                                                         
      var oItem = oEvent.getParameter("selectedItem");                                                                                                                                                                                                         
      this._set("model", oItem ? oItem.getKey() : "");                                                                                                                                                                                                         
      this.onRefresh();                                                                                                                                                                                                                                        
    },                                                                                                                                                                                                                                                         
    onRefresh: function () {                                                                                                                                                                                                                                   
      var iGeneration = this._resetObjects();                                                                                                                                                                                                                  
      if (!this._get("model")) { return; }                                                                                                                                                                                                                     
      this._set("busy", true);                                                                                                                                                                                                                                 
      this._set("status", "Loading objects...");                                                                                                                                                                                                               
      var mTarget = this._target();                                                                                                                                                                                                                            
      var pScripts = this._request("scripts", mTarget).then(function (oData) {                                                                                                                                                                                 
        if (!Array.isArray(oData.scripts)) { throw new Error("Invalid script response."); }                                                                                                                                                                    
        this._scripts = oData.scripts;                                                                                                                                                                                                                         
      }.bind(this));                                                                                                                                                                                                                                           
      var pPackages = this._request("packages", mTarget).then(function (oData) {                                                                                                                                                                               
        if (!Array.isArray(oData.packages)) { throw new Error("Invalid package response."); }                                                                                                                                                                  
        this._packages = oData.packages;                                                                                                                                                                                                                       
      }.bind(this));                                                                                                                                                                                                                                           
      Promise.all([pScripts, pPackages]).then(function () {                                                                                                                                                                                                    
        if (this._destroyed || iGeneration !== this._generation) { return; }                                                                                                                                                                                   
        this._rebuildObjects();                                                                                                                                                                                                                                
        this._set("objectsLoaded", true);                                                                                                                                                                                                                      
        this._set("busy", false);                                                                                                                                                                                                                              
        var iTotal = this._scripts.length + this._packages.length;                                                                                                                                                                                             
        this._set("status", iTotal ? "Select objects to export, or upload an archive to import." : "No objects found. Upload an archive to import new objects.");                                                                                              
      }.bind(this)).catch(function (e) {                                                                                                                                                                                                                       
        if (iGeneration === this._generation) { this._error(e); }                                                                                                                                                                                              
      }.bind(this));                                                                                                                                                                                                                                           
    },                                                                                                                                                                                                                                                         
    _target: function () { return { environment: this._get("environment"), model: this._get("model") }; },                                                                                                                                                     
    _rebuildObjects: function () {                                                                                                                                                                                                                             
      var aObjects = [];                                                                                                                                                                                                                                       
      (this._scripts || []).forEach(function (oScript) {                                                                                                                                                                                                       
        aObjects.push({ category: "Logic Scripts", kind: "script", title: oScript.name, name: oScript.name });                                                                                                                                                 
      });                                                                                                                                                                                                                                                      
      (this._packages || []).forEach(function (oPackage) {                                                                                                                                                                                                     
        aObjects.push({ category: "Data Manager Packages", kind: "package", title: oPackage.id,                                                                                                                                                                
          id: oPackage.id, group: oPackage.group, description: oPackage.description, info: oPackage.group });                                                                                                                                                  
      });                                                                                                                                                                                                                                                      
      this._set("objects", aObjects);                                                                                                                                                                                                                          
      var oList = this.byId("objects");                                                                                                                                                                                                                        
      if (oList) {                                                                                                                                                                                                                                             
        var oBinding = oList.getBinding("items");                                                                                                                                                                                                              
        if (oBinding) { oBinding.sort([this._sorter]); }                                                                                                                                                                                                       
      }                                                                                                                                                                                                                                                        
    },                                                                                                                                                                                                                                                         
    onObjectsSelection: function () {                                                                                                                                                                                                                          
      this._set("selectedCount", this.byId("objects").getSelectedItems().length);                                                                                                                                                                              
    },                                                                                                                                                                                                                                                         
    onSelectAll: function () { this.byId("objects").selectAll(); this.onObjectsSelection(); },                                                                                                                                                                 
    onClearSelection: function () { this.byId("objects").removeSelections(true); this.onObjectsSelection(); },                                                                                                                                                 
    _content: function (mTarget, sName) {                                                                                                                                                                                                                      
      return this._request("script", { environment: mTarget.environment, model: mTarget.model, name: sName }).then(function (oScript) {                                                                                                                        
        Archive.validate(oScript);                                                                                                                                                                                                                             
        if (oScript.name !== sName) { throw new Error("The server returned a different script."); }                                                                                                                                                            
        return oScript;                                                                                                                                                                                                                                        
      });                                                                                                                                                                                                                                                      
    },                                                                                                                                                                                                                                                         
    onExport: function () {                                                                                                                                                                                                                                    
      var aItems = this.byId("objects").getSelectedItems();                                                                                                                                                                                                    
      if (!aItems.length) { return; }                                                                                                                                                                                                                          
      var aScriptNames = [], aPkgRefs = [];                                                                                                                                                                                                                    
      aItems.forEach(function (oItem) {                                                                                                                                                                                                                        
        var oNode = oItem.getBindingContext("bpc").getObject();                                                                                                                                                                                                
        if (oNode.kind === "script") { aScriptNames.push(oNode.name); }                                                                                                                                                                                        
        else { aPkgRefs.push(oNode); }                                                                                                                                                                                                                         
      });                                                                                                                                                                                                                                                      
      var mTarget = this._target(), iGeneration = this._generation;                                                                                                                                                                                            
      var aScripts = [], aPackages = [], iBytes = 0;                                                                                                                                                                                                           
      this._set("busy", true);                                                                                                                                                                                                                                 
      var p = Promise.resolve();                                                                                                                                                                                                                               
      aScriptNames.forEach(function (sName, i) {                                                                                                                                                                                                               
        p = p.then(function () {                                                                                                                                                                                                                               
          if (this._destroyed || iGeneration !== this._generation) { throw new Error("Selection changed. Export cancelled."); }                                                                                                                                
          this._set("status", "Reading script " + (i + 1) + " of " + aScriptNames.length + "...");                                                                                                                                                             
          return this._content(mTarget, sName);                                                                                                                                                                                                                
        }.bind(this)).then(function (oScript) {                                                                                                                                                                                                                
          iBytes += oScript.byteLength;                                                                                                                                                                                                                        
          if (iBytes > 35 * 1024 * 1024) { throw new Error("Select fewer scripts: the export exceeds 35 MB of source content."); }                                                                                                                             
          aScripts.push(oScript);                                                                                                                                                                                                                              
        });                                                                                                                                                                                                                                                    
      }, this);                                                                                                                                                                                                                                                
      aPkgRefs.forEach(function (oPkg) {                                                                                                                                                                                                                       
        p = p.then(function () {                                                                                                                                                                                                                               
          if (this._destroyed || iGeneration !== this._generation) { throw new Error("Selection changed. Export cancelled."); }                                                                                                                                
          return this._request("package", { environment: mTarget.environment, model: mTarget.model, group: oPkg.group, id: oPkg.id });                                                                                                                         
        }.bind(this)).then(function (oDetail) { aPackages.push(oDetail); });                                                                                                                                                                                   
      }, this);                                                                                                                                                                                                                                                
      p.then(function () { return Archive.exportFile(mTarget.environment, mTarget.model, aScripts, aPackages); })                                                                                                                                              
        .then(function (oBlob) {                                                                                                                                                                                                                               
          if (this._destroyed || iGeneration !== this._generation) { return; }                                                                                                                                                                                 
          var sUrl = URL.createObjectURL(oBlob), oLink = document.createElement("a");                                                                                                                                                                          
          oLink.href = sUrl;                                                                                                                                                                                                                                   
          oLink.download = "bpc_" + mTarget.environment + "_" + mTarget.model + "_objects.xml.gz";                                                                                                                                                             
          document.body.appendChild(oLink); oLink.click(); oLink.remove();                                                                                                                                                                                     
          setTimeout(function () { URL.revokeObjectURL(sUrl); }, 10000);                                                                                                                                                                                       
          this._set("busy", false);                                                                                                                                                                                                                            
          this._set("status", "Exported " + (aScripts.length + aPackages.length) + " object(s): " +                                                                                                                                                            
            aScripts.length + " Logic Script(s), " + aPackages.length + " Data Manager Package(s).");                                                                                                                                                          
        }.bind(this)).catch(function (e) { if (iGeneration === this._generation) { this._error(e); } }.bind(this));                                                                                                                                            
    },                                                                                                                                                                                                                                                         
    onUpload: function () {                                                                                                                                                                                                                                    
      if (!this._get("model")) { return; }                                                                                                                                                                                                                     
      if (this._fileInput) { this._fileInput.remove(); }                                                                                                                                                                                                       
      var oInput = document.createElement("input");                                                                                                                                                                                                            
      this._fileInput = oInput;                                                                                                                                                                                                                                
      oInput.type = "file"; oInput.accept = ".gz,.xml"; oInput.style.display = "none";                                                                                                                                                                         
      var iGeneration = this._generation, mTarget = this._target();                                                                                                                                                                                            
      oInput.onchange = function () {                                                                                                                                                                                                                          
        var oFile = oInput.files[0]; oInput.remove();                                                                                                                                                                                                          
        if (!oFile || iGeneration !== this._generation) { return; }                                                                                                                                                                                            
        this._set("importResults", []);                                                                                                                                                                                                                        
        this._set("importSummary", "");                                                                                                                                                                                                                        
        this._set("packageImportSummary", "");                                                                                                                                                                                                                 
        this._set("busy", true);                                                                                                                                                                                                                               
        this._set("status", "Reading archive...");                                                                                                                                                                                                             
        Archive.read(oFile).then(function (oArchive) {                                                                                                                                                                                                         
          if (this._destroyed || iGeneration !== this._generation) { return; }                                                                                                                                                                                 
          var aScripts = oArchive.scripts || [], aPackages = oArchive.packages || [];                                                                                                                                                                          
          this._set("archivePackages", aPackages);                                                                                                                                                                                                             
          var pPrepare = Promise.resolve();                                                                                                                                                                                                                    
          if (aScripts.length) {                                                                                                                                                                                                                               
            pPrepare = this._request("scripts", mTarget).then(function (oData) {                                                                                                                                                                               
              if (this._destroyed || iGeneration !== this._generation) { return; }                                                                                                                                                                             
              if (!Array.isArray(oData.scripts)) { throw new Error("Cannot verify active scripts."); }                                                                                                                                                         
              var mActive = Object.create(null);                                                                                                                                                                                                               
              oData.scripts.forEach(function (s) { mActive[s.name.toUpperCase()] = s.name; });                                                                                                                                                                 
              aScripts.forEach(function (s) {                                                                                                                                                                                                                  
                s.activeName = mActive[s.name.toUpperCase()] || "";                                                                                                                                                                                            
                s.status = s.activeName ? "Exists in SAP" : "New script";                                                                                                                                                                                      
              });                                                                                                                                                                                                                                              
              this._set("uploaded", aScripts);                                                                                                                                                                                                                 
            }.bind(this));                                                                                                                                                                                                                                     
          } else {                                                                                                                                                                                                                                             
            this._set("uploaded", []);                                                                                                                                                                                                                         
          }                                                                                                                                                                                                                                                    
          pPrepare.then(function () {                                                                                                                                                                                                                          
            if (this._destroyed || iGeneration !== this._generation) { return; }                                                                                                                                                                               
            this._set("archiveSource", "Archive: " + oArchive.environment + " / " + oArchive.model +                                                                                                                                                           
              " | Destination: " + mTarget.environment + " / " + mTarget.model);                                                                                                                                                                               
            this._set("busy", false);                                                                                                                                                                                                                          
            this.byId("app").to(this.byId("comparePage"));                                                                                                                                                                                                     
            if (aScripts.length) {                                                                                                                                                                                                                             
              this.byId("uploadedScripts").removeSelections(true);                                                                                                                                                                                             
              this._compare(aScripts[0]);                                                                                                                                                                                                                      
              this.byId("uploadedScripts").setSelectedItem(this.byId("uploadedScripts").getItems()[0]);                                                                                                                                                        
            }                                                                                                                                                                                                                                                  
          }.bind(this));                                                                                                                                                                                                                                       
        }.bind(this)).catch(function (e) { if (iGeneration === this._generation) { this._error(e); } }.bind(this));                                                                                                                                            
      }.bind(this);                                                                                                                                                                                                                                            
      document.body.appendChild(oInput); oInput.click();                                                                                                                                                                                                       
    },                                                                                                                                                                                                                                                         
    onUploadedSelect: function (oEvent) {                                                                                                                                                                                                                      
      this._compare(oEvent.getParameter("listItem").getBindingContext("bpc").getObject());                                                                                                                                                                     
    },                                                                                                                                                                                                                                                         
    _compare: function (oUploaded) {                                                                                                                                                                                                                           
      var iSequence = ++this._compareSequence;                                                                                                                                                                                                                 
      this._set("compareTitle", oUploaded.name);                                                                                                                                                                                                               
      this._set("uploadedText", Archive.display(oUploaded.content));                                                                                                                                                                                           
      this._set("activeText", "");                                                                                                                                                                                                                             
      this._set("compareStatus", oUploaded.activeName ? "Loading active SAP content..." : "New script: no active version exists in the selected model.");                                                                                                      
      this._set("previewBusy", !!oUploaded.activeName);                                                                                                                                                                                                        
      if (!oUploaded.activeName) { return; }                                                                                                                                                                                                                   
      this._content(this._target(), oUploaded.activeName).then(function (oActive) {                                                                                                                                                                            
        if (this._destroyed || iSequence !== this._compareSequence) { return; }                                                                                                                                                                                
        this._set("activeText", Archive.display(oActive.content));                                                                                                                                                                                             
        this._set("previewBusy", false);                                                                                                                                                                                                                       
        oUploaded.status = oActive.content === oUploaded.content ? "Identical" : "Changed";                                                                                                                                                                    
        this._set("compareStatus", oUploaded.status === "Identical" ? "The script contents are identical." : "The uploaded script differs from the active SAP version.");                                                                                      
        this._data.updateBindings(true);                                                                                                                                                                                                                       
      }.bind(this)).catch(function (e) {                                                                                                                                                                                                                       
        if (this._destroyed || iSequence !== this._compareSequence) { return; }                                                                                                                                                                                
        this._set("previewBusy", false);                                                                                                                                                                                                                       
        this._set("compareStatus", e.status === 404 ? "The active script no longer exists. Return and upload again to refresh." : "Active content unavailable: " + e.message);                                                                                 
      }.bind(this));                                                                                                                                                                                                                                           
    },                                                                                                                                                                                                                                                         
    onImport: function () {                                                                                                                                                                                                                                    
      var aScripts = this._get("uploaded") || [], aPackages = this._get("archivePackages") || [], mTarget = this._target();                                                                                                                                    
      if ((!aScripts.length && !aPackages.length) || !mTarget.model) {                                                                                                                                                                                         
        MessageBox.error("The archive contains no objects to import.");                                                                                                                                                                                        
        return;                                                                                                                                                                                                                                                
      }                                                                                                                                                                                                                                                        
      var bReplace = this.byId("replaceExisting").getSelected();                                                                                                                                                                                               
      var bReplacePkgs = this.byId("replacePackages").getSelected();                                                                                                                                                                                           
      var iPlanned = aScripts.filter(function (s) { return bReplace || !s.activeName; }).length;                                                                                                                                                               
      var sScriptsMsg = aScripts.length ? aScripts.length + " script(s)" : "";                                                                                                                                                                                 
      var sPkgsMsg = aPackages.length ? aPackages.length + " package(s)" : "";                                                                                                                                                                                 
      var sAnd = (aScripts.length && aPackages.length) ? " and " : "";                                                                                                                                                                                         
      var sScriptDetail = aScripts.length ? iPlanned + " script(s) will be written. " : "";                                                                                                                                                                    
      var sPkgDetail = aPackages.length ? (bReplacePkgs ? "Existing packages will be replaced." : "Only missing packages will be created.") : "";                                                                                                              
      MessageBox.confirm(                                                                                                                                                                                                                                      
        "Import " + sScriptsMsg + sAnd + sPkgsMsg + " into " + mTarget.environment + " / " + mTarget.model + ". " +                                                                                                                                            
        sScriptDetail + sPkgDetail, {                                                                                                                                                                                                                          
          title: "Import Objects",                                                                                                                                                                                                                             
          onClose: function (sAction) {                                                                                                                                                                                                                        
            if (sAction === MessageBox.Action.OK) { this._submitImport(mTarget, aScripts, bReplace, aPackages, bReplacePkgs); }                                                                                                                                
          }.bind(this)                                                                                                                                                                                                                                         
        });                                                                                                                                                                                                                                                    
    },                                                                                                                                                                                                                                                         
    _submitImport: function (mTarget, aScripts, bReplace, aPackages, bReplacePkgs) {                                                                                                                                                                           
      this._set("importBusy", true);                                                                                                                                                                                                                           
      this._set("importResults", []);                                                                                                                                                                                                                          
      this._set("importSummary", "");                                                                                                                                                                                                                          
      this._set("packageImportSummary", "");                                                                                                                                                                                                                   
      this._set("busy", true);                                                                                                                                                                                                                                 
      var p = Promise.resolve();                                                                                                                                                                                                                               
      if (aScripts.length) {                                                                                                                                                                                                                                   
        p = p.then(function () {                                                                                                                                                                                                                               
          var mData = { environment: mTarget.environment, model: mTarget.model, count: aScripts.length };                                                                                                                                                      
          if (bReplace) { mData.replace = "X"; }                                                                                                                                                                                                               
          aScripts.forEach(function (oScript, i) {                                                                                                                                                                                                             
            mData["name" + (i + 1)] = oScript.name;                                                                                                                                                                                                            
            mData["content" + (i + 1)] = oScript.content;                                                                                                                                                                                                      
          });                                                                                                                                                                                                                                                  
          this._set("status", "Importing " + aScripts.length + " script(s)...");                                                                                                                                                                               
          return this._request("import", mData, "POST").then(function (oData) {                                                                                                                                                                                
            if (!Array.isArray(oData.results)) { throw new Error("Invalid import response."); }                                                                                                                                                                
            this._set("importResults", oData.results);                                                                                                                                                                                                         
            this._set("importSummary", oData.changed + " script(s) written, " + oData.skipped + " skipped, " + oData.failed + " failed.");                                                                                                                     
            return oData;                                                                                                                                                                                                                                      
          }.bind(this));                                                                                                                                                                                                                                       
        }.bind(this));                                                                                                                                                                                                                                         
      }                                                                                                                                                                                                                                                        
      if (aPackages.length) {                                                                                                                                                                                                                                  
        p = p.then(function () { return this._submitPackageImport(mTarget, aPackages, bReplacePkgs); }.bind(this));                                                                                                                                            
      }                                                                                                                                                                                                                                                        
      p.then(function () {                                                                                                                                                                                                                                     
        this._set("importBusy", false);                                                                                                                                                                                                                        
        this._set("busy", false);                                                                                                                                                                                                                              
        this.onRefresh();                                                                                                                                                                                                                                      
      }.bind(this)).catch(function (e) {                                                                                                                                                                                                                       
        this._set("importBusy", false);                                                                                                                                                                                                                        
        this._error(e);                                                                                                                                                                                                                                        
      }.bind(this));                                                                                                                                                                                                                                           
    },                                                                                                                                                                                                                                                         
    _submitPackageImport: function (mTarget, aPackages, bReplace) {                                                                                                                                                                                            
      var mData = { environment: mTarget.environment, model: mTarget.model, count: aPackages.length };                                                                                                                                                         
      if (bReplace) { mData.replace = "X"; }                                                                                                                                                                                                                   
      aPackages.forEach(function (oPackage, i) {                                                                                                                                                                                                               
        mData["group" + (i + 1)] = oPackage.group;                                                                                                                                                                                                             
        mData["id" + (i + 1)] = oPackage.id;                                                                                                                                                                                                                   
        mData["description" + (i + 1)] = oPackage.description || "";                                                                                                                                                                                           
        mData["type" + (i + 1)] = oPackage.type || "";                                                                                                                                                                                                         
        mData["userGroup" + (i + 1)] = oPackage.userGroup || "";                                                                                                                                                                                               
        mData["chain" + (i + 1)] = oPackage.chain || "";                                                                                                                                                                                                       
        mData["team" + (i + 1)] = oPackage.team || "";                                                                                                                                                                                                         
        mData["script" + (i + 1)] = oPackage.script || "";                                                                                                                                                                                                     
      });                                                                                                                                                                                                                                                      
      this._set("status", "Importing " + aPackages.length + " package(s)...");                                                                                                                                                                                 
      return this._request("packages/import", mData, "POST").then(function (oData) {                                                                                                                                                                           
        if (!Array.isArray(oData.results)) { throw new Error("Invalid package import response."); }                                                                                                                                                            
        this._set("packageImportSummary", "Package import: " + oData.changed + " written, " + oData.skipped + " skipped, " + oData.failed + " failed.");                                                                                                       
        if (oData.failed) { MessageBox.warning("Some packages could not be written. See the status for details."); }                                                                                                                                           
        return oData;                                                                                                                                                                                                                                          
      }.bind(this));                                                                                                                                                                                                                                           
    },                                                                                                                                                                                                                                                         
    onBack: function () {                                                                                                                                                                                                                                      
      this._compareSequence++;                                                                                                                                                                                                                                 
      this.byId("app").back();                                                                                                                                                                                                                                 
      this._set("status", "Select objects to export, or upload another archive to import.");                                                                                                                                                                   
    },                                                                                                                                                                                                                                                         
    onExit: function () {                                                                                                                                                                                                                                      
      this._destroyed = true;                                                                                                                                                                                                                                  
      this._generation++; this._compareSequence++;                                                                                                                                                                                                             
      if (this._fileInput) { this._fileInput.remove(); }                                                                                                                                                                                                       
      this._requests.slice().forEach(function (r) { r.abort(); });                                                                                                                                                                                             
    }                                                                                                                                                                                                                                                          
  });                                                                                                                                                                                                                                                          
});                                                                                                                                                                                                                                                            